
(()=>{
'use strict';

/* User-supplied field item models, downsampled for mobile and embedded offline. */
Object.assign(WORLD_ASSETS,{"survival_bandage":{"name":"survival_bandage","meshes":[{"material":0,"position":"","normal":"","uv":"","index":""}],"images":["assets/9eccdc37443db1bd.jpg"],"textures":[{"source":0}],"materials":[{"pbrMetallicRoughness":{"baseColorFactor":[1,1,1,1],"roughnessFactor":0.30000000000000004,"metallicFactor":0.0,"baseColorTexture":{"index":0}},"doubleSided":true}]},"survival_vending":{"name":"survival_vending","meshes":[{"material":0,"position":"PfADv9Azaj5PnoQ+PvADv9Azaj5PnoS+PfADv4V83T5PnoQ+PvADv4V83T5PnoS+","normal":"AACAPwAAAAC7FfezAACAPwAAAAC7FfezAACAPwAAAAC7FfezAACAPwAAAAC7Ffez","uv":"qwlpP4iUVT6rCWk/eAuDPW2VWj+IlFU+bZVaP3gLgz0=","index":"AAAAAAEAAAADAAAAAAAAAAMAAAACAAAA"},{"material":1,"position":"FKGrvFz/4z94WO0++KCrvFqzXD94WO0+FqGrvFz/4z/oj6K++qCrvFqzXD/oj6K+","normal":"AACAPzG2czO44KOxAACAPzG2czO44KOxAACAPzG2czO44KOxAACAPzG2czO44KOx","uv":"wV+XPuzMYz7CX5c+bj71Ps8PAz/szGM+0A8DP24+9T4=","index":"AgAAAAAAAAABAAAAAgAAAAEAAAADAAAA"},{"material":2,"position":"","normal":"","uv":"","index":""}],"images":["assets/fbb6c0d284104166.jpg","assets/fbb6c0d284104166.jpg"],"textures":[{"source":0},{"source":1}],"materials":[{"pbrMetallicRoughness":{"baseColorFactor":[1,1,1,1],"roughnessFactor":0.5,"metallicFactor":0.0,"baseColorTexture":{"index":0}},"doubleSided":true},{"pbrMetallicRoughness":{"baseColorFactor":[0.0,0.0,0.0,1.0],"roughnessFactor":0.85,"metallicFactor":0.0},"doubleSided":true},{"pbrMetallicRoughness":{"baseColorFactor":[1,1,1,1],"roughnessFactor":0.7,"metallicFactor":0.0,"baseColorTexture":{"index":1}},"doubleSided":true}]},"survival_coin":{"name":"survival_coin","meshes":[{"material":0,"position":"","normal":"","uv":"","index":""}],"images":["assets/fde5cc52e92b8837.jpg"],"textures":[{"source":0}],"materials":[{"pbrMetallicRoughness":{"baseColorFactor":[1,1,1,1],"roughnessFactor":0.85,"metallicFactor":0.0,"baseColorTexture":{"index":0}},"doubleSided":true}]},"survival_monster":{"name":"survival_monster","meshes":[{"material":0,"position":"","normal":"","uv":"","index":""}],"images":["assets/912ecbcc198adc26.webp"],"textures":[{"source":0}],"materials":[{"pbrMetallicRoughness":{"baseColorFactor":[1,1,1,1],"roughnessFactor":0.85,"metallicFactor":0.0,"baseColorTexture":{"index":0}},"doubleSided":true}]}});

const inv=window.inventory;
if(!inv)throw new Error('Inventory system is unavailable.');

const survival={
 hp:100,maxHp:100,
 proximityStart:5.5,contactDeath:1.65,
 vendingUses:0,
 pickups:[],
 cans:[],
 vending:null,
 radio:null,
 deathByHP:false,
 setupDone:false,
 originalDescriptor:inv.descriptor.bind(inv),
 originalName:inv.name.bind(inv),

 updateHealthUI(){
  const pct=clamp(this.hp/this.maxHp*100,0,100);
  const value=$('health-value'),fill=$('health-fill'),critical=$('critical-health');
  if(value)value.textContent=Math.ceil(pct)+'%';
  if(fill){
   fill.style.width=pct+'%';
   fill.style.background=pct<20?'linear-gradient(90deg,#b31d18,#ff3c27)':pct<50?'linear-gradient(90deg,#8d3e31,#c66a4a)':'linear-gradient(90deg,#7f5549,#b89578)';
  }
  if(critical){
   const active=state==='playing'&&pct<20&&pct>0;
   critical.classList.toggle('active',active);
   if(active){
    const depth=(20-pct)/20;
    const pulse=.5+.5*Math.sin(ambientTime*8.2);
    critical.style.opacity=String(clamp(.34+depth*.34+pulse*.08,.34,.78));
   }else critical.style.opacity='0';
  }
 },

 damage(dt){
  if(state!=='playing'||!enemyHasSpawned||this.hp<=0||classic?.battery?.cause)return;
  const dist=Math.hypot(player.x-enemy.x,player.z-enemy.z);
  if(dist>=this.proximityStart||dist<=this.contactDeath)return;
  const py=window.__villageAccess.actualFloor();
  const ey=world.map.floor(enemy.x,enemy.z);
  if(Math.abs(py-ey)>.9||!clearLine(enemy.x,enemy.z,player.x,player.z))return;
  const t=clamp((this.proximityStart-dist)/(this.proximityStart-this.contactDeath),0,1);
  const dps=.8+4.2*t*t;
  this.hp=Math.max(0,this.hp-dps*dt);
  this.updateHealthUI();
  if(this.hp<=0){
   this.deathByHP=true;
   endGame(false);
  }
 },

 heal(amount){
  const before=this.hp;
  this.hp=Math.min(this.maxHp,this.hp+amount);
  this.updateHealthUI();
  return this.hp-before;
 },

 fullRestore(){
  this.hp=this.maxHp;
  staminaMax=Math.min(120,staminaMax+10);
  stamina=staminaMax;
  exhausted=false;
  this.updateHealthUI();
  $('stamina').style.width='100%';
 },

 cloneAsset(name,x,z,opts={}){
  const template=world.assets.templates.get(name);
  if(!template)throw new Error('素材 '+name+' が読み込まれていません');
  const g=template.clone(true);
  g.position.set(x,opts.y??world.map.floor(x,z),z);
  g.rotation.y=opts.rotation||0;
  g.scale.setScalar(opts.scale??1);
  g.name=name+'-runtime';
  if(touchDevice)g.traverse(o=>{if(o.isMesh){o.castShadow=false;o.receiveShadow=false;}});
  scene.add(g);return g;
 },

 freeNear(ax,az,area,r=.55){
  const occupied=()=>[
    ...(archive?.items||[]).filter(p=>p.group?.visible).map(p=>({x:p.x,z:p.z})),
    ...parts.filter(p=>!p.found).map(p=>({x:p.x,z:p.z})),
    ...(revision?.radios||[]).map(p=>({x:p.x,z:p.z}))
  ];
  const occ=occupied();
  for(let ring=0;ring<=6;ring+=.65){
   const steps=ring===0?1:Math.max(8,Math.ceil(ring*8));
   for(let i=0;i<steps;i++){
    const a=steps===1?0:i/steps*Math.PI*2,x=ax+Math.cos(a)*ring,z=az+Math.sin(a)*ring;
    if(!MapManager.inside(x,z,.5)||collision(x,z,r))continue;
    if(area&&world.map.area(x,z)!==area)continue;
    if(occ.some(q=>Math.hypot(q.x-x,q.z-z)<2.2))continue;
    return {x,z};
   }
  }
  throw new Error(area+' の追加アイテム配置地点を確保できません');
 },

 addPickup(type,asset,anchor,area,scale,yOffset=0){
  const p=this.freeNear(anchor[0],anchor[1],area,.45);
  const floor=world.map.floor(p.x,p.z);
  const g=this.cloneAsset(asset,p.x,p.z,{y:floor+yOffset,scale});
  const item={type,x:p.x,z:p.z,group:g,found:false,baseY:floor+yOffset,spin:Math.random()*6.28};
  this.pickups.push(item);return item;
 },

 addVillageRadio(){
  if(!revision)return;
  const p=this.freeNear(67.5,-18.5,'廃村',.7);
  const floor=world.map.floor(p.x,p.z);
  box(1.08,.28,.82,material(0x615c56,{roughness:1}),p.x,floor+.14,p.z);
  const group=world.assets.place('radio',p.x,p.z,{y:floor+.46,rotation:Math.PI,distance:58});
  const lamp=new THREE.Mesh(new THREE.SphereGeometry(.035,6,4),new THREE.MeshBasicMaterial({color:0xffb653}));
  lamp.position.set(p.x,floor+.71,p.z-.29);lamp.visible=false;scene.add(lamp);
  const r={...p,group,lamp,on:false,broken:false,remaining:38,cooldown:0,source:null,gain:null,filter:null,village:true};
  revision.radios.push(r);this.radio=r;
 },

 setup(){
  if(this.setupDone)return;
  this.setupDone=true;

  // One first-aid item and one coin reward the enlarged cave; the second of each sits elsewhere.
  this.addPickup('bandage','survival_bandage',[-88,17],'洞窟',.040,.02);
  this.addPickup('coin','survival_coin',[-64,-20],'洞窟',.014,.070);
  this.addPickup('bandage','survival_bandage',[33,27],'森',.040,.02);
  this.addPickup('coin','survival_coin',[15,-63],'神社',.014,.070);

  const v=this.freeNear(82,-20.5,'廃村',.72);
  const vy=world.map.floor(v.x,v.z);
  this.vending={x:v.x,z:v.z,group:this.cloneAsset('survival_vending',v.x,v.z,{y:vy,scale:1.02,rotation:Math.PI/2}),uses:0};
  addObstacle(v.x,v.z,.62,'vending');
  navReady=false;

  // Two cans are real world drops. They appear only after inserting a coin.
  for(const off of [[1.05,.85],[1.05,-.15]]){
   const x=v.x+off[0],z=v.z+off[1],floor=world.map.floor(x,z);
   const g=this.cloneAsset('survival_monster',x,z,{y:floor+.02,scale:.085,rotation:Math.PI/5});
   g.visible=false;this.cans.push({type:'monster',x,z,group:g,found:false,dispensed:false,baseY:floor+.02,spin:Math.random()*6.28});
  }
  this.addVillageRadio();
 },

 reset(){
  this.hp=this.maxHp=100;this.deathByHP=false;this.vendingUses=0;
  staminaMax=100;stamina=Math.min(stamina,staminaMax);
  for(const p of this.pickups){p.found=false;p.group.visible=true;}
  for(const c of this.cans){c.found=false;c.dispensed=false;c.group.visible=false;}
  if(this.vending)this.vending.uses=0;
  this.updateHealthUI();
 },

 hit(){
  if(state!=='playing')return null;
  const candidates=[...this.pickups,...this.cans.filter(c=>c.dispensed)];
  for(const p of candidates)if(!p.found&&p.group.visible&&Math.hypot(player.x-p.x,player.z-p.z)<2.15&&clearLine(player.x,player.z,p.x,p.z))return {type:'survival-pickup',p};
  const v=this.vending;
  if(v&&Math.hypot(player.x-v.x,player.z-v.z)<2.55)return {type:'vending',v};
  return null;
 },

 pickup(p){
  if(!inv.canAdd()){toast('所持枠がいっぱいだ。何かを使うか、目的地へ運ぼう。',4);audio.tone?.(90,.12,.04,'square',70);return;}
  if(!inv.add({type:p.type,source:p}))return;
  p.found=true;p.group.visible=false;audio.pickup();
  const name=p.type==='bandage'?'バンドエイド':p.type==='coin'?'100円硬貨':'モンスターエナジー';
  toast(name+'を手に入れた。所持 '+inv.count+'/'+inv.max,3.5);updateHUD();
 },

 buy(){
  if(!this.vending)return;
  if(this.vendingUses>=2){toast('売り切れだ。',3);return;}
  const coin=inv.removeType('coin');
  if(!coin){toast('100円硬貨が必要だ。',3);audio.tone?.(90,.12,.04,'square',70);return;}
  const can=this.cans[this.vendingUses];
  this.vendingUses++;this.vending.uses=this.vendingUses;
  can.dispensed=true;can.found=false;can.group.visible=true;
  audio.tone?.(190,.22,.08,'square',120);setTimeout(()=>audio.tone?.(340,.18,.06,'triangle',480),180);
  toast('ガコン……モンスターエナジーが落ちてきた。'+(this.vendingUses>=2?'　SOLD OUT。':''),4);
  updateHUD();
 },

 useSelected(){
  const item=inv.selected&&inv.slots.includes(inv.selected)?inv.selected:null;
  if(!item)return;
  if(item.type==='bandage'){
   if(this.hp>=this.maxHp){toast('今は使う必要がない。',2.5);return;}
   inv.removeMatch(s=>s===item);const healed=this.heal(50);audio.tone?.(220,.22,.07,'sine',390);
   toast('バンドエイドを使った。体力 +'+Math.round(healed)+'。',3);updateHUD();return;
  }
  if(item.type==='monster'){
   inv.removeMatch(s=>s===item);this.fullRestore();audio.tone?.(115,.18,.08,'sawtooth',240);setTimeout(()=>audio.tone?.(440,.35,.07,'triangle',660),110);
   toast('モンスターエナジーを飲んだ。体力全回復・最大スタミナ '+Math.round(staminaMax)+'%。',4.5);updateHUD();return;
  }
 }
};
window.survivalSystem=survival;

/* Extend item names/descriptions without exposing hidden puzzle solutions on the HUD. */
inv.descriptor=function(item){
 if(item?.type==='bandage')return {mark:'＋',kind:'FIRST AID',desc:'応急処置用。使用すると体力を50%回復する。'};
 if(item?.type==='coin')return {mark:'¥',kind:'100 YEN',desc:'古い100円硬貨。使えそうな場所があるかもしれない。'};
 if(item?.type==='monster')return {mark:'M',kind:'ENERGY',desc:'飲むと体力が全回復し、この探索中の最大スタミナが10%増える。'};
 return survival.originalDescriptor(item);
};
inv.name=function(item){
 if(item?.type==='bandage')return 'バンドエイド';
 if(item?.type==='coin')return '100円硬貨';
 if(item?.type==='monster')return 'モンスターエナジー';
 return survival.originalName(item);
};
inv.renderItems=function(){
 const host=document.getElementById('inventory-slots');if(!host)return;host.replaceChildren();
 for(let i=0;i<this.max;i++){
  const item=this.slots[i]||null,d=this.descriptor(item),el=document.createElement('button');
  el.type='button';el.className='inventory-slot'+(item?'':' empty')+(item&&this.selected===item?' selected':'');el.disabled=!item;
  el.innerHTML='<span class="inventory-slot-index">0'+(i+1)+'</span><span class="inventory-item-mark">'+d.mark+'</span><span class="inventory-item-name">'+this.name(item)+'</span><span class="inventory-item-kind">'+d.kind+'</span>';
  if(item)el.onclick=()=>{this.selected=item;this.renderItems();};host.appendChild(el);
 }
 const detail=document.getElementById('inventory-detail');
 if(detail){
  const item=this.selected&&this.slots.includes(this.selected)?this.selected:null,d=this.descriptor(item);
  detail.innerHTML='<h3>'+(item?this.name(item):'所持品スロット')+'</h3><p>'+d.desc+'</p>';
  if(item&&(item.type==='bandage'||item.type==='monster')){
   const b=document.createElement('button');b.className='inventory-use-item';b.type='button';
   b.textContent=item.type==='bandage'?'使用する':'飲む';
   b.onclick=()=>survival.useSelected();detail.appendChild(b);
  }
 }
 this.updateButton();
};


/* Keep random story records from spawning directly on the new fixed field items. */
if(typeof StoryArchive!=='undefined'){
 const survivalStoryPlaceBase=StoryArchive.prototype.place;
 StoryArchive.prototype.place=function(){
  let tries=0;
  do{
   survivalStoryPlaceBase.call(this);
   tries++;
  }while(survival.setupDone&&tries<6&&this.items.some(r=>r.group?.visible&&[...survival.pickups,survival.vending].filter(Boolean).some(p=>Math.hypot(r.x-p.x,r.z-p.z)<2.2)));
 };
}

/* Setup after the existing map/assets/revision/archive initializers have completed. */
const survivalInitBase=init;
init=async function(){
 await survivalInitBase();if(!ready)return;
 ready=false;$('start').disabled=true;
 try{survival.setup();ready=true;$('start').disabled=false;}
 catch(e){ready=false;show('fatal');$('fatal-detail').textContent='回復アイテム・自販機の準備に失敗しました。 '+e.message;console.error(e);}
};

const survivalStartBase=GameManager.prototype.start;
GameManager.prototype.start=function(){
 const result=survivalStartBase.call(this);
 survival.reset();
 return result;
};

const survivalHitBase=getInteraction;
getInteraction=function(){return survival.hit()||survivalHitBase();};

const survivalInteractBase=interact;
interact=function(){
 if(state!=='playing')return;
 const h=survival.hit();
 if(h){
  if(h.type==='survival-pickup')survival.pickup(h.p);
  else if(h.type==='vending')survival.buy();
  return;
 }
 survivalInteractBase();
};

const survivalPlayerBase=updatePlayer;
updatePlayer=function(dt){
 survivalPlayerBase(dt);
 const h=survival.hit();
 if(h){
  show('interaction');
  if(h.type==='vending')$('interaction').textContent=survival.vendingUses>=2?'自販機：売り切れ':inv.has('coin')?'100円を入れる':'自販機を調べる';
  else if(h.type==='survival-pickup')$('interaction').textContent=inv.canAdd()?(h.p.type==='bandage'?'バンドエイドを拾う':h.p.type==='coin'?'100円硬貨を拾う':'モンスターエナジーを拾う'):'所持枠がいっぱい';
 }
 survival.updateHealthUI();
 // Lightweight pickup motion; no extra lights or per-item raycasts.
 for(const p of [...survival.pickups,...survival.cans])if(p.group.visible&&!p.found){
  p.spin+=dt*.8;p.group.rotation.y=p.spin;p.group.position.y=p.baseY+Math.sin(ambientTime*2+p.spin)*.025;
 }
};

const survivalEnemyBase=updateEnemy;
updateEnemy=function(dt){
 const danger=survivalEnemyBase(dt);
 survival.damage(dt);
 return danger;
};

const survivalHudBase=updateHUD;
updateHUD=function(){survivalHudBase();survival.updateHealthUI();};

const survivalEndBase=endGame;
endGame=function(won){
 const result=survivalEndBase(won);
 if(state!=='playing'){const c=$('critical-health');if(c){c.classList.remove('active');c.style.opacity='0';}}
 return result;
};

const survivalRevealBase=revealGameOver;
revealGameOver=function(){
 survivalRevealBase();
 if(survival.deathByHP)$('death-summary').textContent='怪異に体力を削り切られた。　·　'+formatTime(elapsed)+'　·　部品 '+partsFound+'/7';
};

const survivalHomeBase=returnHome;
returnHome=function(){
 survival.deathByHP=false;survival.hp=survival.maxHp;
 const c=$('critical-health');if(c){c.classList.remove('active');c.style.opacity='0';}
 survivalHomeBase();
};

})();
